import { CHAIN_HISTORY, type ChainMonth } from '@/app/research/data/chainHistory'

/**
 * Ethereum Classic's monthly chain history for /research/history, all from Blockscout:
 * - block time, difficulty and hashrate from app/research/data/chainHistory.ts, generated by
 *   scripts/chain-history.mjs, with any later complete month computed here the same way;
 * - transactions and the average fee per transaction from Blockscout's stats service.
 * Only complete months appear, so no point is a partial month read as a whole one.
 */

const BLOCKSCOUT = 'https://etc.blockscout.com'
const STATS = `${BLOCKSCOUT}/stats-service/api/v1/lines`
const DAY = 86400

export interface ActivityMonth {
  month: string
  transactions: number
  avgFeeEtc: number
}

const monthKey = (d: Date) => d.toISOString().slice(0, 7)

/** The first day of the current month, UTC: everything before it is complete. */
function currentMonthStart(): Date {
  const now = new Date()
  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1))
}

async function getJson<T>(url: string, revalidate: number): Promise<T | null> {
  try {
    const response = await fetch(url, { headers: { Accept: 'application/json' }, next: { revalidate } })
    return response.ok ? ((await response.json()) as T) : null
  } catch {
    return null
  }
}

interface BlockAt {
  height: number
  seconds: number
  difficulty: number
}

async function blockAt(height: number): Promise<BlockAt | null> {
  const body = await getJson<{ timestamp?: string; difficulty?: string }>(`${BLOCKSCOUT}/api/v2/blocks/${height}`, DAY)
  const seconds = body?.timestamp ? Date.parse(body.timestamp) / 1000 : NaN
  const difficulty = Number(body?.difficulty)
  return Number.isFinite(seconds) && difficulty > 0 ? { height, seconds, difficulty } : null
}

/** A block within ten minutes of `target` seconds, found from `guess` by the local block time. */
async function blockNear(target: number, guess: number): Promise<BlockAt | null> {
  let b = await blockAt(guess)
  for (let i = 0; b && i < 8 && Math.abs(target - b.seconds) > 600; i++) {
    const probe = await blockAt(Math.max(1, b.height - 1000))
    if (!probe) return null
    const blockTime = (b.seconds - probe.seconds) / (b.height - probe.height) || 13
    b = await blockAt(Math.max(1, b.height + Math.round((target - b.seconds) / blockTime)))
  }
  return b && Math.abs(target - b.seconds) <= 600 ? b : null
}

/**
 * The months after the generated file's last one, up to the last complete month, computed the way
 * scripts/chain-history.mjs computes them. A month that cannot be read ends the top-up: the chart stops
 * at the last known month rather than skipping one.
 */
async function laterMonths(): Promise<ChainMonth[]> {
  const last = CHAIN_HISTORY[CHAIN_HISTORY.length - 1]
  if (!last) return []
  const limit = currentMonthStart()
  const rows: ChainMonth[] = []
  const monthStart = new Date(`${last.month}-01T00:00:00Z`)
  monthStart.setUTCMonth(monthStart.getUTCMonth() + 1)
  let first = await blockNear(monthStart.getTime() / 1000, last.firstBlock + last.blocks)
  while (first && monthStart < limit) {
    const next = new Date(monthStart)
    next.setUTCMonth(next.getUTCMonth() + 1)
    const guess = first.height + Math.round((next.getTime() / 1000 - first.seconds) / 13)
    const end = await blockNear(next.getTime() / 1000, guess)
    if (!end || end.height <= first.height) break
    const blocks = end.height - first.height
    const mid = await blockAt(first.height + Math.floor(blocks / 2))
    if (!mid) break
    const blockTime = (end.seconds - first.seconds) / blocks
    rows.push({
      month: monthKey(monthStart),
      firstBlock: first.height,
      blocks,
      blockTimeSeconds: Math.round(blockTime * 100) / 100,
      difficultyPH: Math.round((mid.difficulty / 1e15) * 1e6) / 1e6,
      hashrateTHs: Math.round((mid.difficulty / blockTime / 1e12) * 1000) / 1000,
    })
    first = end
    monthStart.setUTCMonth(monthStart.getUTCMonth() + 1)
  }
  return rows
}

export async function fetchChainHistory(): Promise<ChainMonth[]> {
  return [...CHAIN_HISTORY, ...(await laterMonths())]
}

type Line = { chart?: { date: string; value: string; is_approximate?: boolean }[] }

/** Monthly transactions and average fee, complete months only. Empty when the stats service is down. */
export async function fetchActivityHistory(): Promise<ActivityMonth[]> {
  const [txns, fees] = await Promise.all([
    getJson<Line>(`${STATS}/newTxns?resolution=MONTH`, DAY),
    getJson<Line>(`${STATS}/averageTxnFee?resolution=MONTH`, DAY),
  ])
  const limit = monthKey(currentMonthStart())
  const feeByMonth = new Map((fees?.chart ?? []).map((point) => [point.date.slice(0, 7), Number(point.value)]))
  return (txns?.chart ?? [])
    .map((point) => ({ month: point.date.slice(0, 7), transactions: Number(point.value), avgFeeEtc: feeByMonth.get(point.date.slice(0, 7)) ?? NaN }))
    .filter((row) => row.month < limit && Number.isFinite(row.transactions) && Number.isFinite(row.avgFeeEtc))
}
